// COMPOSITION: Trade OWNS Fees — fees die with the trade
package com.bank.relationships.model;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Trade {
    private final String tradeId;
    private final String symbol;
    private final BigDecimal amount;

    // ═══ COMPOSITION: Trade CREATES and OWNS fees ═══
    private final List<Fee> fees = new ArrayList<>();
    // Fees are created BY the trade, have no meaning without the trade,
    // and are destroyed when the trade is deleted.
    // In JPA: @OneToMany(cascade = ALL, orphanRemoval = true)

    public Trade(String tradeId, String symbol, BigDecimal amount) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.amount = amount;
        // Trade CREATES its own fees — composition!
        calculateAndAddFees();
    }

    private void calculateAndAddFees() {
        // Brokerage: 0.1% of trade amount
        fees.add(new Fee("BROKERAGE", amount.multiply(new BigDecimal("0.001"))
            .setScale(2, java.math.RoundingMode.HALF_UP)));
        // GST on brokerage: 18%
        BigDecimal brokerage = fees.get(0).getAmount();
        fees.add(new Fee("GST", brokerage.multiply(new BigDecimal("0.18"))
            .setScale(2, java.math.RoundingMode.HALF_UP)));
        // STT: 0.025% of trade amount
        fees.add(new Fee("STT", amount.multiply(new BigDecimal("0.00025"))
            .setScale(2, java.math.RoundingMode.HALF_UP)));
    }

    public BigDecimal getTotalFees() {
        return fees.stream().map(Fee::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    // Return UNMODIFIABLE view — encapsulation!
    public List<Fee> getFees() { return Collections.unmodifiableList(fees); }

    public String getTradeId() { return tradeId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }

    @Override
    public String toString() {
        return tradeId + " " + symbol + " Rs." + amount + " (fees: " + fees + ")";
    }
}
