// AGGREGATION: Department HAS Traders — weak ownership
package com.bank.relationships.model;

import java.util.ArrayList;
import java.util.List;

public class TradingDepartment {
    private final String departmentName;

    // ═══ AGGREGATION: department has traders, but doesn't OWN them ═══
    private final List<Trader> traders = new ArrayList<>();
    // Traders exist independently. Removing from department doesn't destroy them.
    // In JPA: @ManyToMany or @OneToMany WITHOUT cascade delete

    public TradingDepartment(String departmentName) {
        this.departmentName = departmentName;
    }

    public void addTrader(Trader trader) {
        traders.add(trader);
        // Department does NOT create the trader — trader existed before being added
    }

    public void removeTrader(Trader trader) {
        traders.remove(trader);
        // Trader is NOT destroyed — just removed from this department
        // Trader can join another department
    }

    // If department is dissolved → traders survive!
    public List<Trader> dissolve() {
        List<Trader> survivingTraders = new ArrayList<>(traders);
        traders.clear();
        return survivingTraders;  // traders returned — they LIVE ON
    }

    public String getDepartmentName() { return departmentName; }
    public List<Trader> getTraders() { return traders; }
}
