// ─── File: src/test/java/com/bank/relationships/model/ThreeRelationshipsTest.java ───
package com.bank.relationships.model;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ThreeRelationshipsTest {

    // ═══ COMPOSITION: Fee lifecycle bound to Trade ═══
    @Test
    void composition_feesCreatedByTrade() {
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        // Trade CREATES fees in constructor — Trade OWNS them
        assertThat(trade.getFees()).hasSize(3);  // BROKERAGE, GST, STT
        assertThat(trade.getFees().get(0).getFeeType()).isEqualTo("BROKERAGE");
    }

    @Test
    void composition_feesCannotExistWithoutTrade() {
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("100000"));
        List<Fee> fees = trade.getFees();
        // fees are UNMODIFIABLE — caller can't detach fees from trade
        assertThatThrownBy(() -> fees.add(new Fee("FAKE", BigDecimal.ONE)))
            .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void composition_totalFeesCalculated() {
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("100000"));
        // BROKERAGE: 100000 × 0.1% = 100
        // GST: 100 × 18% = 18
        // STT: 100000 × 0.025% = 25
        // Total: 143
        assertThat(trade.getTotalFees()).isEqualByComparingTo("143");
    }

    // ═══ AGGREGATION: Trader survives department dissolution ═══
    @Test
    void aggregation_tradersSurviveDepartmentDissolution() {
        Trader rajesh = new Trader("T001", "Rajesh", "EQUITY");
        Trader priya = new Trader("T002", "Priya", "FOREX");

        TradingDepartment dept = new TradingDepartment("Equity Desk");
        dept.addTrader(rajesh);
        dept.addTrader(priya);

        // Dissolve department:
        List<Trader> survivors = dept.dissolve();

        // Department is empty:
        assertThat(dept.getTraders()).isEmpty();
        // But traders SURVIVE:
        assertThat(survivors).containsExactly(rajesh, priya);
        assertThat(rajesh.getName()).isEqualTo("Rajesh");  // still alive!
    }

    @Test
    void aggregation_traderCanJoinAnotherDepartment() {
        Trader rajesh = new Trader("T001", "Rajesh", "EQUITY");

        TradingDepartment oldDept = new TradingDepartment("Old Desk");
        oldDept.addTrader(rajesh);
        oldDept.removeTrader(rajesh);  // leaves old department

        TradingDepartment newDept = new TradingDepartment("New Desk");
        newDept.addTrader(rajesh);  // joins new department — same object!

        assertThat(oldDept.getTraders()).isEmpty();
        assertThat(newDept.getTraders()).containsExactly(rajesh);
    }

    // ═══ ASSOCIATION: services use each other independently ═══
    @Test
    void association_servicesExistIndependently() {
        // Association is just a reference — neither creates nor destroys the other
        // In Spring: @Autowired / constructor injection = association
        // Replace ClearingHouse implementation → SettlementService unchanged
        assertThat(true).isTrue();  // conceptual — tested via integration
    }

    // ═══ COMPOSITION vs AGGREGATION — the KEY difference ═══
    @Test
    void compositionVsAggregation_lifecycleTest() {
        // COMPOSITION: parent death → children death
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("100000"));
        assertThat(trade.getFees()).hasSize(3);
        // trade = null → fees are garbage collected (no independent reference)

        // AGGREGATION: parent death → children survive
        Trader rajesh = new Trader("T001", "Rajesh", "EQUITY");
        TradingDepartment dept = new TradingDepartment("Desk");
        dept.addTrader(rajesh);
        // dept = null → rajesh still exists (independent reference)
        assertThat(rajesh.getName()).isEqualTo("Rajesh");
    }
}
